async function resolveSegment(tenantId, criteria) {
  const conditions = [eq(clientsTable.tenantId, tenantId)];
  if (criteria.gender) {
    conditions.push(eq(clientsTable.gender, criteria.gender));
  }
  if (criteria.ageMin !== void 0) {
    conditions.push(
      sql`${clientsTable.birthDate} IS NOT NULL AND EXTRACT(YEAR FROM AGE(${clientsTable.birthDate})) >= ${criteria.ageMin}`
    );
  }
  if (criteria.ageMax !== void 0) {
    conditions.push(
      sql`${clientsTable.birthDate} IS NOT NULL AND EXTRACT(YEAR FROM AGE(${clientsTable.birthDate})) <= ${criteria.ageMax}`
    );
  }
  if (criteria.city) {
    conditions.push(ilike(clientsTable.addressCity, `%${criteria.city}%`));
  }
  if (criteria.origin) {
    conditions.push(ilike(clientsTable.origin, `%${criteria.origin}%`));
  }
  if (criteria.tag) {
    conditions.push(
      sql`${criteria.tag} = ANY(${clientsTable.tags})`
    );
  }
  if (criteria.classification) {
    conditions.push(eq(clientsTable.classification, criteria.classification));
  }
  if (criteria.status) {
    conditions.push(eq(clientsTable.status, criteria.status));
  }
  if (criteria.travelPreference) {
    conditions.push(ilike(clientsTable.travelPreference, `%${criteria.travelPreference}%`));
  }
  if (criteria.inactiveDays !== void 0) {
    const threshold = new Date(Date.now() - criteria.inactiveDays * 864e5).toISOString();
    conditions.push(
      sql`NOT EXISTS (
        SELECT 1 FROM reservations r
        WHERE r.client_id = ${clientsTable.id}
          AND r.tenant_id = ${clientsTable.tenantId}
          AND r.status IN ('confirmed', 'completed')
          AND r.created_at >= ${threshold}::timestamptz
      )`
    );
  }
  if (criteria.tier) {
    conditions.push(
      sql`EXISTS (
        SELECT 1 FROM loyalty_members lm
        WHERE lm.client_id = ${clientsTable.id}
          AND lm.tenant_id = ${clientsTable.tenantId}
          AND lm.tier = ${criteria.tier}
      )`
    );
  }
  if (criteria.minPurchaseScore !== void 0) {
    conditions.push(
      sql`EXISTS (
        SELECT 1 FROM client_scores cs
        WHERE cs.client_id = ${clientsTable.id}
          AND cs.tenant_id = ${clientsTable.tenantId}
          AND cs.purchase_score >= ${criteria.minPurchaseScore}
      )`
    );
  }
  if (criteria.maxChurnScore !== void 0) {
    conditions.push(
      sql`NOT EXISTS (
        SELECT 1 FROM client_scores cs
        WHERE cs.client_id = ${clientsTable.id}
          AND cs.tenant_id = ${clientsTable.tenantId}
          AND cs.churn_score > ${criteria.maxChurnScore}
      )`
    );
  }
  if (criteria.tripId) {
    conditions.push(
      sql`EXISTS (
        SELECT 1 FROM reservations r
        WHERE r.client_id = ${clientsTable.id}
          AND r.tenant_id = ${clientsTable.tenantId}
          AND r.trip_id = ${criteria.tripId}
      )`
    );
  }
  const rows = await db.select({ id: clientsTable.id }).from(clientsTable).where(and(...conditions));
  return { count: rows.length, clientIds: rows.map((r2) => r2.id) };
}
