async function streamArraySection(opts) {
  let cursor;
  let count2 = 0;
  while (true) {
    const batch = await opts.fetchBatch(cursor);
    if (batch.length === 0) break;
    for (const row of batch) {
      const formatted = opts.formatRow(row);
      await writeExportChunk(opts.res, `${count2 > 0 ? "," : ""}${JSON.stringify(formatted)}`);
      count2++;
    }
    cursor = opts.getCursor(batch[batch.length - 1]);
    if (batch.length < opts.batchSize) break;
  }
  return count2;
}
