        const allFileKeys = [];
        let offset = 0;
        while (true) {
          const page = await utapi.listFiles({ limit: PAGE_SIZE2, offset });
          for (const f3 of page.files) allFileKeys.push(f3.key);
          if (!page.hasMore) break;
          offset += PAGE_SIZE2;
        }
