// src/routes/insights.ts
function brazilUTC2(year, month1Based, day) {
  return new Date(Date.UTC(year, month1Based - 1, day, 3, 0, 0, 0));
}
function getPeriodRange(period) {
  const now = /* @__PURE__ */ new Date();
  const todayBR = localToday();
  const [brYear, brMonth1, brDay] = todayBR.split("-").map(Number);
  let start;
  let end;
  let prevStart;
  let prevEnd;
  if (period === "month") {
    start = brazilUTC2(brYear, brMonth1, 1);
    end = new Date(brazilUTC2(brYear, brMonth1 + 1, 1).getTime() - 1);
    prevStart = brazilUTC2(brYear, brMonth1 - 1, 1);
    prevEnd = new Date(brazilUTC2(brYear, brMonth1, 1).getTime() - 1);
  } else if (period === "quarter") {
    start = brazilUTC2(brYear, brMonth1 - 2, 1);
    end = now;
    prevStart = brazilUTC2(brYear, brMonth1 - 5, 1);
    prevEnd = new Date(brazilUTC2(brYear, brMonth1 - 2, 1).getTime() - 1);
  } else {
    start = brazilUTC2(brYear, 1, 1);
    end = now;
    prevStart = brazilUTC2(brYear - 1, 1, 1);
    prevEnd = new Date(brazilUTC2(brYear, 1, 1).getTime() - 1);
  }
  const momCurrStart = brazilUTC2(brYear, brMonth1, 1);
  const momCurrEnd = now;
  const momPrevStart = brazilUTC2(brYear, brMonth1 - 1, 1);
  const momPrevEnd = new Date(brazilUTC2(brYear, brMonth1, 1).getTime() - 1);
  const yoyPrevStart = brazilUTC2(brYear - 1, 1, 1);
  const yoyPrevEnd = new Date(brazilUTC2(brYear - 1, brMonth1, brDay + 1).getTime() - 1);
  return { start, end, prevStart, prevEnd, momCurrStart, momCurrEnd, momPrevStart, momPrevEnd, yoyPrevStart, yoyPrevEnd };
}
async function revenueInRange(tenantId, from, to5) {
  const [row] = await db.select({ total: sql`coalesce(sum(cast(amount as numeric)), 0)` }).from(paymentsTable).where(and(
    eq(paymentsTable.tenantId, tenantId),
    eq(paymentsTable.type, PAYMENT_TYPE.RECEIVABLE),
    eq(paymentsTable.status, PAYMENT_STATUS.PAID),
    gte(paymentsTable.paidAt, from),
    lte(paymentsTable.paidAt, to5)
  ));
  return Number(row?.total ?? 0);
}
async function expensesInRange(tenantId, from, to5) {
  const [row] = await db.select({ total: sql`coalesce(sum(cast(amount as numeric)), 0)` }).from(expensesTable).where(and(eq(expensesTable.tenantId, tenantId), gte(expensesTable.createdAt, from), lte(expensesTable.createdAt, to5)));
  return Number(row?.total ?? 0);
}
