    router47.post("/client/me/loyalty/redeem", async (req, res, next) => {
      try {
        const me5 = await requireAuth(req, res);
        if (!me5) return;
        if (me5.role !== ROLES.CLIENT) {
          next(new ForbiddenError("Acesso restrito a clientes", "FORBIDDEN_ROLE"));
          return;
        }
        const body5 = external_exports.object({
          reservationId: external_exports.string().min(1),
          pointsToRedeem: external_exports.number().int().positive()
        }).safeParse(req.body);
        if (!body5.success) {
          next(new ValidationError2(String(body5.error.message)));
          return;
        }
        const client = await findClientRecord(me5.tenantId, me5.id, me5.email);
        if (!client) {
          next(new NotFoundError("Perfil de cliente n\xE3o encontrado", "NOT_FOUND"));
          return;
        }
        const [reservation] = await db.select({
          id: reservationsTable.id,
          reservationNumber: reservationsTable.reservationNumber,
          totalValue: reservationsTable.totalValue,
          paidValue: reservationsTable.paidValue,
          status: reservationsTable.status
        }).from(reservationsTable).where(and(
          eq(reservationsTable.id, body5.data.reservationId),
          eq(reservationsTable.clientId, client.id),
          eq(reservationsTable.tenantId, me5.tenantId)
        )).limit(1);
        if (!reservation) {
          next(new NotFoundError("Reserva n\xE3o encontrada", "NOT_FOUND"));
          return;
        }
        const balance = Math.max(Number(reservation.totalValue) - Number(reservation.paidValue), 0);
        if (balance <= 0) {
          next(new ValidationError2("Esta reserva n\xE3o possui saldo pendente"));
          return;
        }
        if (reservation.status === RESERVATION_STATUS.CANCELLED) {
          next(new ValidationError2("N\xE3o \xE9 poss\xEDvel resgatar pontos em reservas canceladas"));
          return;
        }
        const [loyaltyProgram] = await db.select().from(loyaltyProgramsTable).where(and(eq(loyaltyProgramsTable.tenantId, me5.tenantId), eq(loyaltyProgramsTable.isActive, true))).limit(1);
        if (!loyaltyProgram) {
          next(new NotFoundError("Programa de fidelidade n\xE3o ativo", "NOT_FOUND"));
          return;
        }
        const [member] = await db.select().from(loyaltyMembersTable).where(and(
          eq(loyaltyMembersTable.tenantId, me5.tenantId),
          eq(loyaltyMembersTable.programId, loyaltyProgram.id),
          eq(loyaltyMembersTable.clientId, client.id)
        )).limit(1);
        if (!member) {
          next(new NotFoundError("Voc\xEA n\xE3o \xE9 membro do programa de fidelidade", "NOT_FOUND"));
          return;
        }
        if (body5.data.pointsToRedeem < loyaltyProgram.minRedeemPoints) {
          next(new ValidationError2(`O m\xEDnimo para resgate \xE9 ${loyaltyProgram.minRedeemPoints} pontos`));
          return;
        }
        if (member.availablePoints < loyaltyProgram.minRedeemPoints) {
          next(new ValidationError2(`S\xE3o necess\xE1rios pelo menos ${loyaltyProgram.minRedeemPoints} pontos para resgatar`));
          return;
        }
        if (body5.data.pointsToRedeem > member.availablePoints) {
          next(new ValidationError2("Pontos insuficientes"));
          return;
        }
        const realPerPoint = Number(loyaltyProgram.realPerPoint);
        let result;
        await db.transaction(async (tx) => {
          const [lockedMember] = await tx.select({ availablePoints: loyaltyMembersTable.availablePoints }).from(loyaltyMembersTable).where(eq(loyaltyMembersTable.id, member.id)).for("update").limit(1);
          if (!lockedMember) throw new ValidationError2("Membro n\xE3o encontrado");
          if (lockedMember.availablePoints < loyaltyProgram.minRedeemPoints) {
            throw new ValidationError2(`S\xE3o necess\xE1rios pelo menos ${loyaltyProgram.minRedeemPoints} pontos para resgatar`);
          }
          if (lockedMember.availablePoints < body5.data.pointsToRedeem) {
            throw new ValidationError2("Pontos insuficientes (tente novamente)");
          }
          const [lockedReservation] = await tx.select({
            totalValue: reservationsTable.totalValue,
            paidValue: reservationsTable.paidValue,
            reservationNumber: reservationsTable.reservationNumber
          }).from(reservationsTable).where(eq(reservationsTable.id, reservation.id)).for("update").limit(1);
          if (!lockedReservation) throw new ValidationError2("Reserva n\xE3o encontrada");
          const currentBalance = Math.max(
            Number(lockedReservation.totalValue) - Number(lockedReservation.paidValue),
            0
          );
          if (currentBalance <= 0) throw new ValidationError2("Esta reserva n\xE3o possui saldo pendente");
          const maxPointsByBalance = Math.floor(currentBalance / realPerPoint);
          if (maxPointsByBalance < 1) {
            throw new ValidationError2("Saldo da reserva insuficiente para resgate (menor que 1 ponto)");
          }
          const actualPointsRedeemed = Math.min(body5.data.pointsToRedeem, maxPointsByBalance);
          if (actualPointsRedeemed < loyaltyProgram.minRedeemPoints) {
            throw new ValidationError2(`O m\xEDnimo para resgate \xE9 ${loyaltyProgram.minRedeemPoints} pontos (saldo dispon\xEDvel permite ${maxPointsByBalance})`);
          }
          const discountAmount = actualPointsRedeemed * realPerPoint;
          const newAvailablePoints = lockedMember.availablePoints - actualPointsRedeemed;
          await tx.update(loyaltyMembersTable).set({ availablePoints: newAvailablePoints }).where(eq(loyaltyMembersTable.id, member.id));
          const txId = generateId();
          await tx.insert(loyaltyTransactionsTable).values({
            id: txId,
            tenantId: me5.tenantId,
            memberId: member.id,
            type: "redeem",
            points: actualPointsRedeemed,
            description: `Resgate de pontos \u2014 Reserva ${lockedReservation.reservationNumber ?? reservation.id.slice(-6).toUpperCase()}`,
            referenceId: reservation.id,
            referenceType: "reservation"
          });
          await tx.update(reservationsTable).set({
            paidValue: sql`${reservationsTable.paidValue} + ${discountAmount}`,
            discountLoyaltyPoints: sql`COALESCE(${reservationsTable.discountLoyaltyPoints}, 0) + ${actualPointsRedeemed}`,
            discountLoyaltyAmount: sql`COALESCE(${reservationsTable.discountLoyaltyAmount}, '0') + ${discountAmount}`
          }).where(eq(reservationsTable.id, reservation.id));
          result = { pointsRedeemed: actualPointsRedeemed, discountAmount, newAvailablePoints };
        });
        res.json(result);
      } catch (err) {
        next(err);
      }
    });
